// ─── Fetal-sex reveal gate ─────────────────────────────────────────────────────
// Mirrors the patient portal's fetal-sex confirmation flow. Fetal sex is hidden by
// default and only revealed after the patient explicitly confirms via a modal — the
// same two-step "Reveal Fetal Sex? → Continue / Cancel" pattern the portal uses.
//
// Scope (product decision, June 2026):
//   • Gated       : ANP summary fetal-sex chips; the cfDNA fetal-risk block for the
//                   X-linked, sex-derived conditions below (DMD, Fragile X).
//   • Never gated : sex-chromosome aneuploidy rows (Monosomy X / XXX / XXY / XYY).
//                   These are clinical results and are always shown — detected or
//                   not — even though they imply fetal sex.
//
// Clinical content is never reworded: for the cfDNA path the approved text is simply
// withheld until acknowledged, then rendered verbatim.
//
// PRODUCTION NOTE: `revealed` should be hydrated from and persisted to a per-patient
// server-side preference so the choice is consistent across desktop + mobile and
// survives sessions. The in-memory state below is the prototype stand-in.
const SEX_REVEALING_CONDITIONS = new Set(["DMD", "FRAGILE_X", "FMR1"]);

const SexRevealContext = createContext({ revealed:false, requestReveal:()=>{}, hide:()=>{} });
function useSexReveal(){ return useContext(SexRevealContext); }

function SexRevealProvider({ children }) {
  const [revealed, setRevealed] = useState(false);
  const [askOpen, setAskOpen]   = useState(false);
  const requestReveal = () => { if(!revealed) setAskOpen(true); };
  const hide          = () => setRevealed(false);
  const confirm       = () => { setRevealed(true); setAskOpen(false); };
  const cancel        = () => setAskOpen(false);
  return (
    <SexRevealContext.Provider value={{ revealed, requestReveal, hide }}>
      {children}
      {askOpen && <ConfirmRevealSexModal onContinue={confirm} onCancel={cancel}/>}
    </SexRevealContext.Provider>
  );
}

// Warning triangle — reused by the modal and the cfDNA acknowledgment card.
function WarnTri({ size=20 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M12 3L22 20H2L12 3Z" stroke={T.coral} strokeWidth="2" strokeLinejoin="round"/>
      <path d="M12 10V14" stroke={T.coral} strokeWidth="2" strokeLinecap="round"/>
      <circle cx="12" cy="17" r="1.1" fill={T.coral}/>
    </svg>
  );
}

// Portal-mirroring confirmation dialog. NOTE: patient-facing copy below requires GC
// sign-off before production.
function ConfirmRevealSexModal({ onContinue, onCancel }) {
  return (
    <div onClick={onCancel} style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(2,38,51,0.45)",backdropFilter:"blur(2px)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="reveal-sex-title"
        style={{background:T.white,borderRadius:16,maxWidth:380,width:"100%",padding:"22px 22px 16px",boxShadow:"0 20px 60px rgba(2,38,51,0.35)",fontFamily:T.font}}>
        <div style={{width:34,height:34,borderRadius:"50%",background:"rgba(244,91,61,0.12)",display:"flex",alignItems:"center",justifyContent:"center",marginBottom:12}}>
          <WarnTri size={20}/>
        </div>
        <h2 id="reveal-sex-title" style={{fontSize:18,fontWeight:700,color:T.dark,margin:"0 0 8px"}}>Reveal Fetal Sex?</h2>
        <p style={{fontSize:13,lineHeight:1.6,color:T.softBlack,margin:"0 0 20px"}}>This will reveal your baby&rsquo;s sex, including in any results that depend on it. Do you wish to continue?</p>
        <div style={{display:"flex",justifyContent:"flex-end",gap:8}}>
          <button onClick={onCancel} style={{padding:"10px 18px",borderRadius:10,fontSize:13,...BTN_SECONDARY}}>Cancel</button>
          <button onClick={onContinue} style={{padding:"10px 18px",borderRadius:10,fontSize:13,...BTN_PRIMARY}}>Continue</button>
        </div>
      </div>
    </div>
  );
}

// Masked-by-default fetal-sex summary. `variant` styles for the light desktop
// sidebar vs the dark mobile result header.
function FetalSexSummary({ list, variant="desktop" }) {
  const { revealed, requestReveal, hide } = useSexReveal();
  const dark = variant === "mobile";
  if (revealed) {
    return (
      <div style={{display:dark?"flex":"block",flexWrap:"wrap",gap:dark?8:0,alignItems:"center"}}>
        {list.map((fs,i)=> dark ? (
          <span key={i} style={{fontSize:11,color:"rgba(255,255,255,0.7)",background:"rgba(255,255,255,0.08)",padding:"3px 9px",borderRadius:20}}>{fs.label}: {fs.sex.charAt(0).toUpperCase()+fs.sex.slice(1)}</span>
        ) : (
          <p key={i} style={{fontSize:12,color:T.textMuted,margin:"2px 0"}}>{fs.label}: {fs.sex.charAt(0).toUpperCase()+fs.sex.slice(1)} fetal sex</p>
        ))}
        <button onClick={hide} style={{...BTN_LINK,fontSize:dark?10:11,padding:0,marginTop:dark?0:2,marginLeft:dark?4:0,color:dark?"rgba(255,255,255,0.6)":T.coral,textDecoration:"underline"}}>Hide</button>
      </div>
    );
  }
  return (
    <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",margin:dark?0:"2px 0"}}>
      <span style={{fontSize:dark?11:12,color:dark?"rgba(255,255,255,0.55)":T.textMuted}}>Fetal sex hidden</span>
      <button onClick={requestReveal}
        style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:11,fontWeight:600,cursor:"pointer",borderRadius:20,padding:"3px 10px",
          background:dark?"rgba(255,255,255,0.1)":"transparent",border:`1px solid ${dark?"rgba(255,255,255,0.3)":T.coral}`,color:dark?"white":T.coral}}>
        Reveal fetal sex
      </button>
    </div>
  );
}

// Non-blocking notice shown on sex-revealing results (DMD / Fragile X). For these
// X-linked conditions the fetal-risk result itself reveals fetal sex, and a clinical
// result is never hidden (same rule as the sex-chromosome aneuploidy rows). So rather
// than gate the content, we surface an informational banner that flags it.
// NOTE: patient-facing copy — requires GC sign-off before production.
function FetalSexNoticeBanner({ style={} }) {
  return (
    <div style={{background:"rgba(244,91,61,0.06)",border:"1px solid rgba(244,91,61,0.35)",borderRadius:8,padding:"10px 12px",display:"flex",gap:8,alignItems:"flex-start",...style}}>
      <span style={{flexShrink:0,marginTop:1}}><WarnTri size={16}/></span>
      <p style={{fontSize:12,lineHeight:1.5,color:T.softBlack,margin:0}}><strong style={{color:T.dark,fontWeight:600}}>This result reveals your baby&rsquo;s sex.</strong> Because this condition is sex-linked, the risk depends on your baby&rsquo;s sex.</p>
    </div>
  );
}

// Renders a branded badge by name; returns null if not yet available.
function IcoBadge({name, size=24, style={}}) {
  const src = ICONS[name];
  if (!src) return null;
  return <img src={src} width={size} height={size} alt="" aria-hidden="true" style={{display:"inline-block",verticalAlign:"middle",flexShrink:0,...style}}/>;
}
