// ─── Helpers ──────────────────────────────────────────────────────────────────
const gaStr    = ga  => `${ga.weeks}w ${ga.days}d`;
const fmtDate  = iso => { try { return new Date(iso+"T00:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}); } catch { return iso; } };
const panelLabel = { acog_guideline:"ACOG Guideline Panel", plus_panel:"Plus Panel", fragile_x:"Fragile X" };
const recIcon    = { cardiology_eval:"❤️", prenatal_diagnosis:"🔬", genetic_counseling:"💬", other:"ℹ️" };
const ANP_FU_ICONS = { prenatal_diagnosis:"🔬", genetic_counseling:"💬", unity_confirm:"🧬", surveillance:"🩺", redraw:"🔄", other:"ℹ️" };

function getFetalRisk(report, cid) { return report.cfDNA_assessment?.conditions?.find(c=>c.condition_id===cid)||null; }

// Sex-linked (X-linked) fetal-risk mapping. For DMD/FMR1 the fetal risk is always
// present and is driven by the fetal-sex bioinformatics profile code, not by a
// standard cfDNA risk score — so these conditions never fall through to the
// carrier-only ("You are a carrier.") summary copy. Keys are the fetal-sex profile
// codes the pipeline emits; values are the fetal_risk_status to display.
//   DMD (per clinical spec, Chelsea 2026-06-10):
//     male / male_male / male_female / male_one_or_more  → High Risk
//     nocall_final / tnp_gestationalage_redraw / tnp_qns_redraw → High Risk
//     female / female_female → Increased Risk
//   FMR1 / FRAGILE_X: mapping is more complex (repeat size + AGG + fetal sex) and is
//   pending a separate clinical spec — left empty so it falls back to the reported
//   fetal_risk_status until that mapping is provided.
const SEX_LINKED_FETAL_RISK = {
  DMD: {
    male:"high_risk", male_male:"high_risk", male_female:"high_risk", male_one_or_more:"high_risk",
    nocall_final:"high_risk", tnp_gestationalage_redraw:"high_risk", tnp_qns_redraw:"high_risk",
    female:"increased_risk", female_female:"increased_risk",
  },
  FMR1: {}, FRAGILE_X: {},
};
function resolveSexLinkedRisk(conditionId, profileCode) {
  const m = SEX_LINKED_FETAL_RISK[conditionId];
  if (!m) return null;
  return m[(profileCode||"").toLowerCase()] || null;
}
// Maps a condition's human-readable carrier_status to the canonical BI profile
// code used as the key in STATIC_EXPLANATIONS / the static content spreadsheet.
// "negative" → "NEG" (shared CSP & ECP negative content, spreadsheet row 2).
const CARRIER_STATUS_ALIAS = { negative: "NEG" };

function getStaticKey(report, condition) {
  // no_call and qc_fail statuses always use the generic no-call content
  if (condition.carrier_status==="no_call"||condition.carrier_status==="qc_fail") return "__NO_CALL__";
  // Manual override map (e.g. SMN_SILENT_CARRIER scenario)
  const override = (report.static_explanation_map||{})[condition.condition_id];
  if (override) return override;
  // Try compound key: CONDITION_ID__CARRIER_PROFILE_CODE (e.g. "SICKLE_CELL__POSITIVE_HBS")
  if (condition.carrier_profile_code) {
    const compound = `${condition.condition_id}__${condition.carrier_profile_code}`;
    if (STATIC_EXPLANATIONS[compound]) return compound;
  }
  // Fall back to bare profile code for shared codes (e.g. "SMN_1CN_CARRIER", "NEG_PSEUDO")
  if (condition.carrier_profile_code && STATIC_EXPLANATIONS[condition.carrier_profile_code]) {
    return condition.carrier_profile_code;
  }
  // S-1 (CW 2026-06-10): HBB affected subtypes without a specific reviewed entry
  // collapse to the hemoglobinopathy-scoped key. The three subtypes that DO have
  // reviewed content (HBSS / HBSC / HBSBTHAL) already matched above via the
  // compound key, so only the uncovered POS_AFFECTED_* codes reach this line.
  // The bare generic "POS_AFFECTED" deliberately stays condition-agnostic.
  if (condition.condition_id === "SICKLE_CELL"
      && condition.carrier_profile_code
      && condition.carrier_profile_code.indexOf("POS_AFFECTED") === 0
      && STATIC_EXPLANATIONS["SICKLE_CELL__POS_AFFECTED"]) {
    return "SICKLE_CELL__POS_AFFECTED";
  }
  // Last resort: map the human-readable carrier_status to its canonical BI
  // profile code from the static content map (spreadsheet "Carrier Static
  // Content"). The status vocabulary ("negative") differs from the BI profile
  // code ("NEG"), so an alias is required — otherwise negatives fall through to
  // the UNAVAILABLE state even though reviewed content exists.
  if (condition.carrier_status) {
    const status = condition.carrier_status.toLowerCase();
    const alias = CARRIER_STATUS_ALIAS[status];
    if (alias && STATIC_EXPLANATIONS[alias]) return alias;
    if (STATIC_EXPLANATIONS[condition.carrier_status.toUpperCase()]) {
      return condition.carrier_status.toUpperCase();
    }
  }
  return null;
}

