function GCActionBlock() {
  return (
    <div style={{background:T.beige,borderRadius:12,padding:"14px 16px",display:"flex",flexDirection:"column",gap:10}}>
      <div>
        <p style={{fontSize:13,fontWeight:700,color:T.dark,margin:0}}>Talk to a genetic counselor</p>
        <p style={{fontSize:12,color:T.textMuted,margin:"3px 0 0",lineHeight:1.5}}>Our board-certified genetic counselors can help you understand your results. {SUPPORT_HOURS}.</p>
      </div>
      <a href={GC_SCHEDULE_URL} target="_blank" rel="noopener noreferrer"
        style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,padding:"12px 16px",borderRadius:10,fontSize:14,textDecoration:"none",...BTN_PRIMARY}}>
        <IcoBadge name="schedule" size={22}/> Schedule an appointment
      </a>
      <div style={{display:"flex",gap:8}}>
        <a href={GC_PHONE_TEL}
          style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",gap:8,padding:"11px 12px",background:T.sky,borderRadius:10,border:`0.5px solid ${T.lightAqua}`,textDecoration:"none"}}>
          <IcoBadge name="phone" size={20}/>
          <span style={{fontSize:12,fontWeight:600,color:T.dark}}>{GC_PHONE_DISPLAY}</span>
        </a>
        <a href={`mailto:${SUPPORT_EMAIL}`}
          style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",gap:8,padding:"11px 12px",background:T.sky,borderRadius:10,border:`0.5px solid ${T.lightAqua}`,textDecoration:"none"}}>
          <IcoBadge name="email" size={20}/>
          <span style={{fontSize:12,fontWeight:600,color:T.dark}}>Email us</span>
        </a>
      </div>
    </div>
  );
}
function CarrierStatusBadge({status,small}) {
  const cfg=STATUS_CFG[status]||{label:status,color:T.textMuted,bg:T.gray};
  return (
    <span style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:small?11:12,fontWeight:600,color:cfg.color,background:cfg.bg,padding:small?"2px 7px":"3px 8px",borderRadius:12,whiteSpace:"nowrap"}}>
      <span style={{width:5,height:5,borderRadius:"50%",background:cfg.color,flexShrink:0}}/>{cfg.label}
    </span>
  );
}
function ANPStatusBadge({status,label_override,size="normal"}) {
  const notSca=status==="not_detected_sca";
  const cfg=notSca?{label:"Not Detected",color:"#1E7A38",bg:"#F0FAF3",icon:"✓"}:ANP_STATUS[status]||{label:status,color:T.textMuted,bg:T.gray,icon:"–"};
  const label=label_override||cfg.label;
  const fs=size==="sm"?11:13; const px=size==="sm"?"6px 10px":"5px 12px";
  return (
    <span style={{display:"inline-flex",alignItems:"center",gap:5,background:cfg.bg,color:cfg.color,fontSize:fs,fontWeight:600,padding:px,borderRadius:20,border:`1px solid ${cfg.color}22`,whiteSpace:"nowrap",letterSpacing:status==="high_risk"?"0.4px":"0"}}>
      <span style={{fontSize:fs-1}}>{cfg.icon}</span>{label}
    </span>
  );
}

