// ─── QC Fail bypass screen ────────────────────────────────────────────────────
const ALERT = {
  standard:null,
  high_risk:{ bg:"#F7E9ED",border:"#E3C2CC",icon:"🔴",text:"Your report contains a high-risk fetal result. We strongly recommend reviewing the guide and speaking with a healthcare provider or genetic counselor as soon as possible." },
  no_call:  { bg:"#FFFBEB",border:"#FDDCB5",icon:"⚠️",text:"Your sample returned a No Call result — a new blood draw may be needed. Review the guide to understand what this means and what happens next." },
  qc_fail:  { bg:"#FFFBEB",border:"#FDDCB5",icon:"⚠️",text:"Your sample did not pass quality control. This is a technical issue with the sample, not a result about your genetic status." },
};

// ─── No Call / QC banner ──────────────────────────────────────────────────────
// Prominent top-of-content banner for No Call / QC-fail results (GC feedback E-17).
// Copy is reused verbatim from the reviewed ALERT map — no new clinical language —
// and a working GC scheduling + phone path is surfaced inline per project constraint.
function NoCallBanner({status}) {
  const cfg = ALERT[status];
  if (!cfg) return null;
  return (
    <div style={{background:cfg.bg,border:`1px solid ${cfg.border}`,borderRadius:10,padding:"12px 16px",marginBottom:16,display:"flex",gap:10,alignItems:"flex-start"}}>
      <span style={{fontSize:16,flexShrink:0}}>{cfg.icon}</span>
      <div style={{flex:1,minWidth:0}}>
        <p style={{fontSize:12,color:T.navy,margin:"0 0 8px",lineHeight:1.6}}>{cfg.text}</p>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <a href={GC_SCHEDULE_URL} target="_blank" rel="noopener noreferrer"
            style={{display:"inline-flex",alignItems:"center",gap:6,padding:"8px 14px",borderRadius:8,fontSize:12,textDecoration:"none",...BTN_PRIMARY}}>
            <IcoBadge name="schedule" size={18}/> Schedule a genetic counselor
          </a>
          <a href={GC_PHONE_TEL}
            style={{display:"inline-flex",alignItems:"center",gap:6,padding:"8px 14px",borderRadius:8,fontSize:12,textDecoration:"none",background:"white",border:`0.5px solid ${cfg.border}`,color:T.dark,fontWeight:600}}>
            <IcoBadge name="phone" size={18}/> {GC_PHONE_DISPLAY}
          </a>
        </div>
      </div>
    </div>
  );
}

// ─── Follow-up callout ────────────────────────────────────────────────────────
// Surfaces follow-up recommendations at the top of the main content column
// (relocated from the sidebar per GC feedback E-16) for higher visibility.
function FollowUpCallout({items, iconNameMap, iconEmojiMap}) {
  if (!items || items.length===0) return null;
  return (
    <div style={{background:"#FBF8F5",border:`0.5px solid ${T.border}`,borderLeft:`3px solid ${T.aqua}`,borderRadius:8,padding:"12px 16px",marginBottom:16}}>
      <p style={{fontSize:10,fontWeight:600,color:T.textMuted,textTransform:"uppercase",letterSpacing:"0.5px",margin:"0 0 8px"}}>Recommended follow-up</p>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {items.map((r,i)=>{
          // E-05: the genetic-counseling recommendation row is a working contact
          // action (links to GC scheduling), not just text — so a GC rec never
          // appears without a tappable GC contact path.
          const isGC=r.type==="genetic_counseling";
          const icon=iconNameMap[r.type] ? <IcoBadge name={iconNameMap[r.type]} size={20} style={{marginTop:1}}/> : <span style={{fontSize:13,flexShrink:0,marginTop:1}}>{(iconEmojiMap&&iconEmojiMap[r.type])||"ℹ️"}</span>;
          const body=(
            <div style={{flex:1}}>
              <p style={{fontSize:12,color:T.navy,margin:0,lineHeight:1.55}}>{r.text}</p>
              {isGC&&<span style={{display:"inline-flex",alignItems:"center",gap:4,marginTop:6,fontSize:11,fontWeight:700,color:T.coral,textTransform:"uppercase",letterSpacing:"0.5px"}}>Schedule an appointment ›</span>}
            </div>
          );
          return isGC ? (
            <a key={i} href={GC_SCHEDULE_URL} target="_blank" rel="noopener noreferrer" style={{display:"flex",gap:8,alignItems:"flex-start",textDecoration:"none",cursor:"pointer"}}>{icon}{body}</a>
          ) : (
            <div key={i} style={{display:"flex",gap:8,alignItems:"flex-start"}}>{icon}{body}</div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Shared nav bar ───────────────────────────────────────────────────────────
